let playlist=[];let currentIndex=0;let touchStartX=0;let touchEndX=0;let isAnimating=!1;let containers=[];document.addEventListener('DOMContentLoaded',()=>{playlist=document.querySelectorAll('.video a[data-youtube-id]');const original=document.querySelector('.lightbox-container');const clone=original.cloneNode(!0);document.getElementById('video-lightbox').appendChild(clone);containers=[original,clone];original.classList.add('lc-active');setupContainerEvents(original);setupContainerEvents(clone)});function setupContainerEvents(container){container.querySelector('.lightbox-close').addEventListener('click',closeLightbox);container.addEventListener('click',(e)=>{e.stopPropagation()})}
document.addEventListener('click',function(e){const link=e.target.closest('.video a');if(link&&link.getAttribute('data-youtube-id')){e.preventDefault();currentIndex=Array.from(playlist).indexOf(link);openLightbox(currentIndex)}});function loadContent(container,index){if(index<0||index>=playlist.length)return;const element=playlist[index];container.querySelector('#lb-title').innerText=element.querySelector('h4').innerText;container.querySelector('#lb-desc').innerText=element.getAttribute('data-desc')||"";container.querySelector('#lb-link').href=element.getAttribute('href');container.querySelector('#lb-iframe').src="https://www.youtube.com/embed/"+element.getAttribute('data-youtube-id')+"?autoplay=1&rel=0&vq=hd1080&modestbranding=1"}
function openLightbox(index){const activeContainer=document.querySelector('.lightbox-container.lc-active');loadContent(activeContainer,index);document.getElementById('video-lightbox').classList.add('active');document.body.style.overflow='hidden'}
function changeVideo(direction){if(isAnimating)return;isAnimating=!0;let newIndex=currentIndex+direction;if(newIndex>=playlist.length)newIndex=0;if(newIndex<0)newIndex=playlist.length-1;currentIndex=newIndex;const current=document.querySelector('.lightbox-container.lc-active');const next=containers.find(c=>c!==current);loadContent(next,currentIndex);next.classList.add(direction===1?'set-pos-right':'set-pos-left');void next.offsetWidth;next.classList.remove('set-pos-right','set-pos-left');current.classList.add(direction===1?'anim-out-left':'anim-out-right');current.classList.remove('lc-active');next.classList.add('lc-active');setTimeout(()=>{current.querySelector('#lb-iframe').src="";current.classList.remove('anim-out-left','anim-out-right');isAnimating=!1},600)}
function closeLightbox(){const lightbox=document.getElementById('video-lightbox');lightbox.classList.remove('active');setTimeout(()=>{containers.forEach(c=>c.querySelector('#lb-iframe').src="")},300);document.body.style.overflow='auto'}
document.getElementById('video-lightbox').addEventListener('click',closeLightbox);document.addEventListener('keydown',function(e){if(!document.getElementById('video-lightbox').classList.contains('active'))return;if(e.key==="ArrowRight")changeVideo(1);if(e.key==="ArrowLeft")changeVideo(-1);if(e.key==="Escape")closeLightbox();});document.addEventListener('touchstart',(e)=>{touchStartX=e.changedTouches[0].screenX},{passive:!0});document.addEventListener('touchend',(e)=>{if(!document.getElementById('video-lightbox').classList.contains('active'))return;touchEndX=e.changedTouches[0].screenX;if(Math.abs(touchStartX-touchEndX)>50)changeVideo(touchStartX>touchEndX?1:-1);},{passive:!0})